import React from 'react';
import './Menu.css';

const Menu = () => {
  const menuItems = [
    {
      id: 1,
      name: 'Kofta',
      price: 250,
      description: "Soft, spicy koftas soaking in rich, creamy gravy — a bite of pure bliss in every spoonful.",
      image: 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398',
      veg: true
    },
    {
      id: 2,
      name: 'Samosha',
      price: 180,
      description: "Crispy outside, spicy inside — a samosa is not just a snack, it's an emotion wrapped in crunch.",
      image: 'https://images.unsplash.com/photo-1601050690597-df0568f70950',
      veg: true
    },
    {
      id: 3,
      name: 'Rogan Josh',
      price: 280,
      description: 'Aromatic lamb curry from Kashmir',
      image: 'https://images.unsplash.com/photo-1603360946369-dc9bb6258143',
      veg: false
    }
  ];

  const handleOrder = (item) => {
    alert(`Order placed for ${item.name}! Our staff will contact you shortly.`);
  };

  return (
    <div className="menu-page">
      <div className="menu-header">
        <h1>Hotel Shyam Special Menu</h1>
        <p>Authentic flavors crafted with traditional recipes</p>
      </div>

      <div className="menu-items-container">
        {menuItems.map(item => (
          <div key={item.id} className="menu-item">
            <div className="item-image">
              <img src={item.image} alt={item.name} />
              <span className={`food-tag ${item.veg ? 'veg' : 'non-veg'}`}>
                {item.veg ? 'VEG' : 'NON-VEG'}
              </span>
            </div>
            <div className="item-details">
              <h3>{item.name}</h3>
              <p className="item-description">{item.description}</p>
              <div className="item-footer">
                <span className="item-price">₹{item.price}</span>
                <button 
                  className="order-now-btn"
                  onClick={() => handleOrder(item)}
                >
                  Order Now
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Menu;
